head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭 또는 Source 탭에서 autoComplete1 부분을 확인한다.
    //1. In the Script tab or Source tab, check the autoComplete1 section.
    //Verify 1. autoComplete1.setItemSet( "data:dataList1" , "label" , "value"   );
    //Test step 2. autoComplete1  의 chooseOptionLabel 부분을 확인한다.
    //2. Check the chooseOptionLabel part of autoComplete1.
    //Verify 2. chooseOptionLabel='= 선택 ='
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_label').textContent == '= 선택 ='", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 브라우저에서 autoComplete 에 동적설정의 리스트를 확인한다.
    //3. Check the list of dynamic settings in autoComplete in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. = 선택 = / 하나 / 둘둘 데이터가 표현된다. (그전버전에서는 = 선택 = 은 표시안되고, 하나 / 둘둘만 표현됨)
    //3. = Select = / One / two data is represented. (In the previous version = select = is not displayed, only one / two is expressed)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_itemTable_0').textContent == '= 선택 ='", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_itemTable_1').textContent == '하나'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_itemTable_2').textContent == '둘둘'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setJSON([{
            "label": "하나",
            "value": "11"
        },
        {
            "label": "둘둘",
            "value": "22"
        }
    ]);
    autoComplete1.setItemSet("data:dataList1", "label", "value");
    selectbox1.setNodeSet("data:dataList1", "label", "value");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 21-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
